-- Hide scraping debris in the dish catalogue: 693 entries that can never be a dish name
-- (control characters, addresses with phone numbers and "klant reviews", cookie and terms text,
-- spam domains, menu codes like "S22"). Selected on 2026-11-13 with the strict rule in
-- supabase/tests/dish-junk.ts, which leaves real dishes with long descriptions alone.
-- Nothing is deleted: dishes become inactive (set is_active = true to undo), and a dish that a
-- restaurant has approved stays active. Open suggestions pointing at them are marked rejected so
-- owners don't see empty rows. Idempotent on purpose (Lovable may apply it under another number, or twice).
DROP TABLE IF EXISTS pg_temp.junk_dish_ids;
CREATE TEMP TABLE junk_dish_ids (id uuid PRIMARY KEY);
ON CONFLICT DO NOTHING;

DELETE FROM junk_dish_ids j
WHERE EXISTS (SELECT 1 FROM public.restaurant_dishes rd
              WHERE rd.dish_id = j.id AND rd.status IN ('verified_by_owner', 'approved_by_admin'));

UPDATE public.restaurant_dishes rd SET status = 'rejected', rejected_reason = 'Geen gerecht: opgeschoonde rommel uit de catalogus'
WHERE rd.status = 'suggested' AND rd.dish_id IN (SELECT id FROM junk_dish_ids);

UPDATE public.dishes d SET is_active = false
WHERE d.is_active AND d.id IN (SELECT id FROM junk_dish_ids);

DROP TABLE IF EXISTS pg_temp.junk_dish_ids;
